    function run(uint256 amount) public payable {
        uint256 before = address(c).balance;
        c.deposit{value: amount}();
        assert(address(c).balance == before + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint256 before = address(c).balance;
        c.deposit{value: amount}();
        c.refund();
        assert(address(c).balance == before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amt, uint256 wd) public payable {
        require(amt > 0);
        require(wd <= amt);
        require(address(this).balance >= amt);
        c.deposit{value: amt}();
        uint256 before = address(c).balance;
        c.withdraw(wd);
        assert(address(c).balance + wd == before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amt) public payable {
        require(amt > 0);
        require(address(this).balance >= amt);
        c.deposit{value: amt}();
        c.refund();
        uint balAfterFirst = address(c).balance;
        c.refund();
        uint balAfterSecond = address(c).balance;
        assert(balAfterSecond == balAfterFirst && balAfterFirst == address(c).balance);
    }
    receive() external payable {}
}
